mutation {
  sellingPlanGroupCreate(
    input: {name: "Assinatura mensal"},
    resources: {productIds: ["gid://shopify/Product/1"]}
  ) { sellingPlanGroup { id } }
}

// dentro da mutation, o campo sellingPlansToCreate declara cada plano:
sellingPlansToCreate: [
  { name: "Mensal", billingPolicy: { recurring: { interval: MONTH, intervalCount: 1 } } },
  { name: "Trimestral", billingPolicy: { recurring: { interval: MONTH, intervalCount: 3 } } }
]

mutation {
  sellingPlanGroupCreate(
    input: { name: "Pré-venda" },
    resources: { productIds: ["gid://shopify/Product/<id>"] }
  ) { sellingPlanGroup { id } }
}

pricingPolicies: [{
  fixed: { adjustmentType: PERCENTAGE, adjustmentValue: { percentage: 15 } }
}],
deliveryPolicy: { fixed: { fulfillmentExactTime: "2025-06-01T00:00:00Z" } }
